#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreApi: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CoreApi

    public static func lift(_ handle: UInt64) throws -> CoreApi {
        return CoreApi(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CoreApi) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreApi {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CoreApi, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreApi_lift(_ handle: UInt64) throws -> CoreApi {
    return try FfiConverterTypeCoreApi.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreApi_lower(_ value: CoreApi) -> UInt64 {
    return FfiConverterTypeCoreApi.lower(value)
}






/**
 * The `olaz-core` actor handle exported to Swift.
 *
 * Owns session, transport, and conversations/conversation-actions state (boot, QR login, expiry,
 * logout, WebSocket lifecycle, long-poll loop, event routing, conversation list/filters/labels,
 * pin/archive/delete/unread/hidden actions) over the shared [`CoreSession`] and [`CoreStore`].
 * Swift pushes commands via sync/async methods and pulls coalesced updates via [`Self::next_changes`].
 */
public protocol CoreEngineProtocol: AnyObject, Sendable {
    
    /**
     * Answers the active composer confirm dialog (schedules 300 ms promotion if queued).
     */
    func answerComposerConfirm(confirmId: String, ok: Bool) 
    
    /**
     * Answers the active message-action confirmation dialog (`ok = true` executes, `false` cancels).
     */
    func answerMessageConfirm(ok: Bool, nowMs: Int64) 
    
    /**
     * Applies an account profile update and returns the monotonic change revision once reduced.
     * Swift awaits this revision in its `next_changes()` mirror before returning from
     * `async func applyAccountProfile(_:)`.
     */
    func applyAccountProfile(account: LoginAccountRecord) async throws  -> UInt64
    
    func applyBatchDirect(payloadJson: String, defaultCmd: UInt16, fallbackConvId: String?, isGroupHint: Bool?, incrementUnread: Bool, notifyIncoming: Bool, persistConversations: Bool, probeFreshness: Bool, nowMs: Int64?) async throws  -> Int64
    
    /**
     * Applies server-fetched pinned and archived conversation ID sets during bootstrap sync.
     */
    func applyBootstrapPinArchive(pinnedIds: [String]?, archivedIds: [String]?) async throws  -> UInt64
    
    func applyParsedEventsDirect(events: [WireEvent], incrementUnread: Bool, notifyIncoming: Bool, persistConversations: Bool) async throws  -> Int64
    
    /**
     * Applies a standalone recall/delete [`ConvPreviewOverrideRecord`] and awaits store persistence.
     */
    func applyPreviewOverride(overrideRec: ConvPreviewOverrideRecord, persistConversations: Bool) async throws  -> UInt64
    
    /**
     * Applies an already-fetched server hidden-conversations snapshot.
     */
    func applyServerHiddenConversations(pin: String, threadIds: [String]) async throws  -> UInt64
    
    /**
     * Presents a host-originated confirmation dialog (e.g. pin / unpin) in core's confirm slot.
     */
    func askMessageConfirm(confirm: MessageConfirmRecord) 
    
    /**
     * Attaches the account's opened [`CoreStore`] so `olaz-core` can hydrate local conversation
     * state and run serial SQLite persistence directly without Swift hops.
     */
    func attachStore(store: CoreStore) 
    
    func bootstrap(nowMs: Int64) async throws  -> UInt64
    
    /**
     * Checks whether `pin` matches the stored hidden-chat PIN digest (MD5 or offline SHA-256).
     */
    func checkHiddenPin(pin: String) async throws  -> Bool
    
    func clearBoardCaches() 
    
    /**
     * Dismisses the active forward picker request (e.g. sheet closed by user).
     */
    func clearForwardRequest() 
    
    func closeConversation() 
    
    /**
     * Deletes the specified zCloud item keys via server API + remote-delete + snapshot refresh.
     */
    func cloudDelete(keys: [String]) async throws  -> CloudActionResultRecord
    
    /**
     * Downloads/resolves a cloud item for preview/save via `Host::resolve_media`/`resolve_file`.
     */
    func cloudFetch(key: String) async throws  -> CloudFetchRecord
    
    /**
     * Queries a sorted, paginated page of zCloud items (SQLite + unsynced in-memory merge).
     */
    func cloudList(convId: String?, kind: CloudItemKindRecord?, sortBySize: Bool, ascending: Bool, offset: Int64, limit: Int64) async throws  -> CloudPageRecord
    
    /**
     * Attempts to toggle zCloud auto-offload (unsupported on Olaz; clears offload flags).
     */
    func cloudSetOffload(enabled: Bool) async throws  -> CloudActionResultRecord
    
    /**
     * Resolves a cloud item's thumbnail via `Host::resolve_media`.
     */
    func cloudThumbnail(key: String) async throws  -> MediaResolutionRecord
    
    /**
     * Reports a composer outcome (`Failed` / `Pending` emit `show_card`).
     */
    func composerReport(convId: String, outcome: ComposerOutcomeRecord) 
    
    /**
     * Deletes a conversation on the server, in SQLite, and in memory.
     */
    func confirmDeleteConversation(id: String, lastCliMsgId: String) 
    
    func contactCardState(uid: String) async throws  -> ContactCardStateRecord
    
    func contactProfile(uid: String) async throws  -> ContactProfileRecord?
    
    /**
     * Creates a new conversation label using caller-supplied `now_ms` and `rand4` for deterministic IDs.
     */
    func createConversationLabel(name: String, colorHex: String, conversationIds: [String], nowMs: Int64, rand4: String) 
    
    func createPoll(convId: String, draft: PollCreateDraftRecord, config: PollConfigRecord, canPin: Bool) async throws  -> PollActionOutcomeRecord
    
    /**
     * Creates a reminder (enforces official title limits before HTTP).
     */
    func createReminder(convId: String, title: String, startMs: Int64, repeatMode: Int64, pin: Bool) async throws  -> ComposerOutcomeRecord
    
    /**
     * Returns the latest monotonic revision published to the change stream.
     */
    func currentVersion()  -> UInt64
    
    /**
     * Deletes a conversation label.
     */
    func deleteConversationLabel(id: String) 
    
    /**
     * Deletes a single message only for the current user (shows confirm when `!confirmed` and
     * `menu.delete == forMe`, else removes optimistically and starts the 5 s undo bar).
     */
    func deleteForMe(convId: String, msgId: String, confirmed: Bool, nowMs: Int64) 
    
    /**
     * Deletes multiple selected messages only for the current user.
     */
    func deleteMany(convId: String, msgIds: [String], confirm: Bool, nowMs: Int64) 
    
    /**
     * Detaches any attached [`CoreStore`] handle.
     */
    func detachStore() 
    
    /**
     * Clears the active conversation prompt.
     */
    func dismissConversationPrompt() 
    
    /**
     * Dismisses the active 5 s delete-undo bar and commits the pending delete immediately.
     */
    func dismissDeleteUndo() 
    
    /**
     * Runs up to `max_batches` HTTP long-poll fetches serially (ADR-018) and returns the total
     * number of events applied across those batches.
     */
    func drainChatPolling(maxBatches: UInt32, notifyIncoming: Bool) async throws  -> UInt32
    
