#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CoreEngine

    public static func lift(_ handle: UInt64) throws -> CoreEngine {
        return CoreEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CoreEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CoreEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreEngine_lift(_ handle: UInt64) throws -> CoreEngine {
    return try FfiConverterTypeCoreEngine.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreEngine_lower(_ value: CoreEngine) -> UInt64 {
    return FfiConverterTypeCoreEngine.lower(value)
}






/**
 * Platform host callbacks implemented by Swift (`ZaloEngineCoreHost`).
 *
 * Called serially in emitted order on the core's host worker; never invoked concurrently.
 * `snapshot_json` in `persist_session` / `mark_expired` contains credentials and must never be
 * logged.
 */
public protocol CoreHost: AnyObject, Sendable {
    
    func loadSavedSession() async  -> String?
    
    func loadLegacyCookie() async  -> LegacyCookieRecord?
    
    func loadTransportState() async  -> PersistedTransportStateRecord
    
    func setPref(key: String, value: String) async 
    
    func prepareStore(userId: String, account: LoginAccountRecord) async 
    
    /**
     * Return `true` to connect WebSocket, `false` to suppress (used by session/transport recorders).
     */
    func onWsStarted(endpoints: [String]) async  -> Bool
    
    /**
     * Return `true` to start periodic long-poll ticks, `false` to suppress.
     */
    func onLongPollStarted() async  -> Bool
    
    func onBootstrapStarted() async  -> Bool
    
    func applyMutes(mutes: [MuteEntryRecord]) async 
    
    func refreshCloud() async 
    
    func onBatchReceived(cmd: UInt16?, incrementUnread: Bool, notifyIncoming: Bool, payloadJson: String) async  -> String?
    
    func onParsedEventsReceived(cmd: UInt16, incrementUnread: Bool, notifyIncoming: Bool, events: [WireEvent], uids: [String], payload: CoreWirePayload) async  -> Bool
    
    func onOpenConversationSync(convId: String, changed: Bool) async 
    
    func onCloseConversation() async 
    
    func refreshBoardPins(convId: String) async 
    
    func markReadBoundary(convId: String, seenTarget: SeenTargetRecord?) async 
    
    func applyRemoteReaction(convId: String, msgId: String, cliMsgId: String, senderId: String, rType: String, rIcon: String, eventId: String, reactClientId: String, senderName: String) async  -> Bool
    
    func applyRemoteRecall(convId: String, msgId: String, cliMsgId: String, updateConversationPreview: Bool, persistConversations: Bool) async  -> Bool
    
    func applyRemoteDelete(convId: String, msgId: String, cliMsgId: String, updateConversationPreview: Bool, persistConversations: Bool) async  -> Bool
    
    func decryptEnvelope(payloadJson: String) async  -> String
    
    func markE2eeConversations(convIds: [String]) async 
    
    func notePollMessages(messages: [ChatMessageRecord]) async 
    
    func notifyIncomingMessages(messages: [ChatMessageRecord]) async 
    
    func showBatchTyping(convId: String, senderId: String) async 
    
    func transportBatchSettled() async 
    
    func engineLog(message: String) async 
    
    func offerFirstLoginTransfer(force: Bool) async 
    
    func resetDomains() async 
    
    func persistSession(snapshotJson: String) async 
    
    func clearSession() async 
    
    func markExpired(snapshotJson: String) async 
    
    func persistPollState(state: PollStateRecord) async 
    
    func persistWsCursors(cursors: [CursorEntry]) async 
    
    func mobileSync(events: [MobileSyncEventRecord]) async 
    
    func e2eeSignal(cmd: UInt16, payloadJson: String) async 
    
    func e2eeDeliverReports(cmd: UInt16, payloadJson: String) async 
    
    func e2eeConnected(uid: String) async 
    
    func e2eeDisconnected() async 
    
    func voipControl(act: String, rawDataJson: String, dataJson: String) async 
    
    func showTyping(convId: String, uid: String, onPc: Bool) async 
    
    func pinTopic(convId: String) async 
    
    func groupNotice(act: String, dataJson: String, ts: Int64) async 
    
    func mute(convId: String, set: Bool, start: Int64, startExplicit: Bool, duration: Int64) async 
    
    func sendE2eeText(convId: String, text: String, clientId: String, quote: E2eeQuoteArgRecord?) async  -> E2eeSendOutcomeRecord
    
    func showCard(convId: String?, text: String) async 
    
    func resolveMedia(convId: String, msgId: String, kind: String) async  -> MediaResolutionRecord
    
    func resolveFile(convId: String, msgId: String, name: String, url: String?) async  -> FileResolutionRecord
    
    func fetchMediaData(url: String) async  -> String?
    
    func sendMedia(convId: String, paths: [String], cleanupAfter: Bool) async  -> ComposerSendOutcomeRecord
    
    func sendFiles(convId: String, paths: [String]) async  -> ComposerSendOutcomeRecord
    
    func armPollDebounce(pollId: String, seq: UInt64, delayMs: UInt64) async  -> Bool
    
    func cancelAllPollDebounces() async 
    
    func notifyBanners(banners: [NotifyBannerPayloadRecord]) async 
    
    func requestNotifAuth() async  -> NotifAuthorizationRecord
    
    func startCall(uid: String, video: Bool) async 
    
    func sendCategorySticker(convId: String, cateId: Int32, stickerId: Int32) async  -> CardActionOutcomeRecord
    
    func refreshContacts() async 
    
    func armReminderWatchTimer(waiterId: UInt64, delaySecs: Double) async  -> Bool
    
    func cancelReminderWatchTimer(waiterId: UInt64) async 
    
    func sendE2eeSticker(convId: String, cateId: Int64, stickerId: Int64, clientId: String) async  -> E2eeStickerSendOutcomeRecord
    
    func sendE2eeContactCard(convId: String, clientId: String, contactUid: String, title: String, phone: String, avatar: String, qrCodeUrl: String) async  -> E2eeSendOutcomeRecord
    
    func sleepConfirmPromote(delayMs: UInt64) async 
    
}
/**
 * Platform host callbacks implemented by Swift (`ZaloEngineCoreHost`).
 *
 * Called serially in emitted order on the core's host worker; never invoked concurrently.
 * `snapshot_json` in `persist_session` / `mark_expired` contains credentials and must never be
 * logged.
 */
open class CoreHostImpl: CoreHost, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_olaz_ffi_fn_clone_corehost(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_olaz_ffi_fn_free_corehost(handle, $0) }
    }

    

    
