/**
 * A running socket session. Dropping the last reference (Swift `deinit`) stops it.
 */
public protocol WsSessionProtocol: AnyObject, Sendable {
    
    func currentCursors() async throws  -> [CursorEntry]
    
    func isAuthed() async throws  -> Bool
    
    func seedCursors(cursors: [CursorEntry]) async throws 
    
    /**
     * Sends a raw frame. `false` unless authenticated and the write succeeded.
     */
    func sendFrame(cmd: UInt16, subCmd: UInt8, version: UInt8, payloadJson: String?) async throws  -> Bool
    
    /**
     * Sends a request frame and waits for its response (default 10 s). `inner_data_json` is a
     * JSON object (empty string for none). `None`: not authenticated, send failed, timed out,
     * disconnected or stopped.
     */
    func sendRequest(cmd: UInt16, subCmd: UInt8, reqId: String?, innerDataJson: String) async throws  -> String?
    
    /**
     * Like `send_request` with an explicit timeout in seconds.
     */
    func sendRequestWithTimeout(cmd: UInt16, subCmd: UInt8, reqId: String?, innerDataJson: String, timeoutSecs: Double) async throws  -> String?
    
    /**
     * Updates the uid / "My Cloud" id typed envelopes are parsed with.
     */
    func setParseContext(myUid: String, selfConvId: String?) 
    
    /**
     * Closes the socket and ends the session; returns the cursors left (empty after a reset).
     * Pass them as `seed_cursors` to a later `ws_start` to resume.
     */
    func stop(resetCursors: Bool) async throws  -> [CursorEntry]
    
    /**
     * Waits up to `timeout_secs` for the upload `file_id` to finish; the file URL or `None`.
     */
    func waitForFileDone(fileId: String, timeoutSecs: Double) async throws  -> String?
    
}
