public struct FfiConverterTypeWsSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = WsSession

    public static func lift(_ handle: UInt64) throws -> WsSession {
        return WsSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: WsSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WsSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

