 * One decoded push/pull event. `payload_json` is the decrypted body as JSON text; parse it with
 * `parse_wire_batch` / `parse_wire_event` (ids are exact there).
 */
public struct WsEventRecord: Equatable, Hashable {
    public var cmd: UInt16
    public var subCmd: UInt8
    public var version: UInt8
    public var payloadJson: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(cmd: UInt16, subCmd: UInt8, version: UInt8, payloadJson: String) {
        self.cmd = cmd
        self.subCmd = subCmd
        self.version = version
        self.payloadJson = payloadJson
    }

    

    
}

