/**
 * One parsed realtime / history event (`ParsedWireEvent`).
 */

public enum WireEvent: Equatable, Hashable {
    
    case message(
        /**
         * Fully typed message (kind, quote, reactions, mentions, menu...).
         */message: ChatMessageRecord, stored: WireStored
    )
    case reaction(convId: String, msgId: String, cliMsgId: String, senderId: String, rType: String, rIcon: String, eventId: String, reactClientId: String, tsMs: Int64, seqId: Int64, senderName: String
    )
    case undo(convId: String, msgId: String, cliMsgId: String
    )
    case delete(convId: String, msgId: String, cliMsgId: String
    )
    case typing(convId: String, senderId: String, isGroup: Bool
    )
    case ignore





}

#if compiler(>=6)
extension WireEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWireEvent: FfiConverterRustBuffer {
    typealias SwiftType = WireEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WireEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .message(message: try FfiConverterTypeChatMessageRecord.read(from: &buf), stored: try FfiConverterTypeWireStored.read(from: &buf)
        )
        
        case 2: return .reaction(convId: try FfiConverterString.read(from: &buf), msgId: try FfiConverterString.read(from: &buf), cliMsgId: try FfiConverterString.read(from: &buf), senderId: try FfiConverterString.read(from: &buf), rType: try FfiConverterString.read(from: &buf), rIcon: try FfiConverterString.read(from: &buf), eventId: try FfiConverterString.read(from: &buf), reactClientId: try FfiConverterString.read(from: &buf), tsMs: try FfiConverterInt64.read(from: &buf), seqId: try FfiConverterInt64.read(from: &buf), senderName: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .undo(convId: try FfiConverterString.read(from: &buf), msgId: try FfiConverterString.read(from: &buf), cliMsgId: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .delete(convId: try FfiConverterString.read(from: &buf), msgId: try FfiConverterString.read(from: &buf), cliMsgId: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .typing(convId: try FfiConverterString.read(from: &buf), senderId: try FfiConverterString.read(from: &buf), isGroup: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .ignore
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WireEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .message(message,stored):
            writeInt(&buf, Int32(1))
            FfiConverterTypeChatMessageRecord.write(message, into: &buf)
            FfiConverterTypeWireStored.write(stored, into: &buf)
            
        
        case let .reaction(convId,msgId,cliMsgId,senderId,rType,rIcon,eventId,reactClientId,tsMs,seqId,senderName):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(convId, into: &buf)
            FfiConverterString.write(msgId, into: &buf)
            FfiConverterString.write(cliMsgId, into: &buf)
            FfiConverterString.write(senderId, into: &buf)
            FfiConverterString.write(rType, into: &buf)
            FfiConverterString.write(rIcon, into: &buf)
            FfiConverterString.write(eventId, into: &buf)
            FfiConverterString.write(reactClientId, into: &buf)
            FfiConverterInt64.write(tsMs, into: &buf)
            FfiConverterInt64.write(seqId, into: &buf)
            FfiConverterString.write(senderName, into: &buf)
            
        
        case let .undo(convId,msgId,cliMsgId):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(convId, into: &buf)
            FfiConverterString.write(msgId, into: &buf)
            FfiConverterString.write(cliMsgId, into: &buf)
            
        
        case let .delete(convId,msgId,cliMsgId):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(convId, into: &buf)
            FfiConverterString.write(msgId, into: &buf)
            FfiConverterString.write(cliMsgId, into: &buf)
            
        
        case let .typing(convId,senderId,isGroup):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(convId, into: &buf)
            FfiConverterString.write(senderId, into: &buf)
            FfiConverterBool.write(isGroup, into: &buf)
            
        
        case .ignore:
            writeInt(&buf, Int32(6))
        
        }
    }
}


